(function(root){
 const collator=new Intl.Collator('zh-CN',{numeric:true,sensitivity:'base'});
 function key(value){const text=String(value??'').trim();if(!text||/^(—|–|-|资料不足|未知|待确认|未填写|尚未)/.test(text))return{missing:true,text};const date=text.match(/^(20\d{2})(?:-(\d{2}))?(?:-(\d{2}))?(?:\s|$|~|至)/);if(date)return{kind:'date',number:Number(date[1]+(date[2]||'00')+(date[3]||'00')),text};const amount=text.match(/^(?:([A-Z]{3})\s*|[¥￥$€£]\s*)?([+\-−]?\s*\d[\d,]*(?:\.\d+)?)\s*(万|亿)?(?:\s*元)?$/);if(amount){let n=Number(amount[2].replaceAll(',','').replaceAll('−','-').replaceAll(' ',''));n*=amount[3]==='万'?10000:amount[3]==='亿'?100000000:1;return{kind:'number',currency:amount[1]||'',number:n,text};}return{kind:'text',text};}
 function compare(a,b,direction=1){a=key(a);b=key(b);if(a.missing||b.missing)return a.missing===b.missing?0:a.missing?1:-1;if(a.kind===b.kind&&a.kind!=='text'){const currency=collator.compare(a.currency||'',b.currency||'');return direction*(currency||a.number-b.number);}return direction*collator.compare(a.text,b.text);}
 if(typeof module!=='undefined'&&module.exports){module.exports={key,compare};return;}
 const states=new WeakMap(),orders=new WeakMap(),listStates=new WeakMap();let scheduled=false;const config={childList:true,subtree:true};
 function text(cell){const direct=[...cell.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();return direct||cell.textContent.trim();}
 function remember(rows){rows.forEach((r,i)=>{if(!orders.has(r))orders.set(r,i);});}
 function orderRows(parent,rows,column,direction,extract){remember(rows);rows.sort((a,b)=>direction?(compare(extract(a,column),extract(b,column),direction)||orders.get(a)-orders.get(b)):orders.get(a)-orders.get(b));for(const r of rows)parent.append(r);}
 function table(table){const heads=[...table.querySelectorAll('thead tr:last-child th')];if(!heads.length||!table.tBodies.length)return;let state=states.get(table);if(!state){state={column:-1,direction:0};states.set(table,state);}heads.forEach((th,i)=>{if(!th.querySelector('button.column-sort')){const label=th.textContent.trim();if(!label||label==='操作'||th.querySelector('input,select,button'))return;const b=document.createElement('button');b.type='button';b.className='column-sort';b.textContent=label;b.dataset.label=label;b.onclick=()=>{state.direction=state.column!==i?1:state.direction===1?-1:state.direction===-1?0:1;state.column=i;refresh();};th.replaceChildren(b);}const button=th.querySelector('.column-sort');if(!button)return;const active=state.column===i?state.direction:0;th.setAttribute('aria-sort',active===1?'ascending':active===-1?'descending':'none');button.dataset.direction=String(active);button.setAttribute('aria-label',button.dataset.label+'：'+(active===1?'当前升序，点击降序':active===-1?'当前降序，点击恢复默认':'点击升序排列'));});
 for(const body of table.tBodies){const rows=[...body.rows];if(!rows.length||rows.some(r=>r.cells.length<2||[...r.cells].some(c=>c.colSpan>1)))continue;orderRows(body,rows,state.column,state.direction,(r,c)=>text(r.cells[c]||r.cells[0]));if(body.id==='unifiedAccountRows'){let owner=null;for(const r of body.rows){const current=text(r.cells[0]);r.classList.toggle('account-group-start',owner!==null&&owner!==current);owner=current;}}}}
 const lists=[['accountRows','账户'],['savedExpenseMonths','月份'],['trashRows','记录'],['memberList','成员']];
 function list(id,label){const el=document.getElementById(id);if(!el)return;let state=listStates.get(el);if(!state){state={direction:0,field:'text'};const tools=document.createElement('div');tools.className='list-sort-controls';const title=document.createElement('span');title.textContent=label+'列表排序';const select=document.createElement('select');select.setAttribute('aria-label',label+'列表排序');for(const [v,name]of [['default','默认顺序'],['asc',label+'升序'],['desc',label+'降序']])select.append(new Option(name,v));select.onchange=()=>{state.direction=select.value==='asc'?1:select.value==='desc'?-1:0;refresh();};tools.append(title,select);el.before(tools);listStates.set(el,state);}const rows=[...el.children];if(rows.length<2)return;orderRows(el,rows,0,state.direction,r=>{if(id==='savedExpenseMonths')return r.querySelector('span')?.textContent||r.textContent;if(id==='trashRows')return r.querySelector('strong')?.textContent||r.textContent;return r.firstChild?.textContent||r.textContent;});}
 function refresh(){if(!document.body)return;observer.disconnect();try{document.querySelectorAll('table').forEach(table);for(const [id,label]of lists)list(id,label);}finally{if(document.body)observer.observe(document.body,config);}}
 const observer=new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;refresh();});});document.addEventListener('family-ledger-ready',refresh);document.addEventListener('family-session-ready',refresh);window.addEventListener('hashchange',refresh);refresh();root.FamilyTableSort={refresh};
})(globalThis);
